/**
 * Test signals and measurements for the sound effects (ADR-0010). Signals are generated by ffmpeg's lavfi sources (no
 * recorded material); measurements are plain arithmetic on interleaved stereo Float32 PCM.
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

export interface FxFixtures { beeps: string; sweep: string; speechLike: string; mono44k: string; impulse: string }

const ff = (args: string[]) => execFileSync('ffmpeg', ['-hide_banner', '-v', 'error', '-y', ...args], { stdio: ['ignore', 'ignore', 'pipe'] });

/**
 * WAVs written by ffmpeg lavfi into `dir` (created if missing):
 *  beeps      = 1 kHz 50 ms beeps every 2 s, 12 s, 48 kHz stereo
 *  sweep      = 20 Hz to 20 kHz log sweep, 6 s, 48 kHz stereo
 *  speechLike = 150 Hz pulse train through two formant band-passes, gated at 4 Hz, 10 s, 48 kHz stereo
 *  mono44k    = the beeps at 44.1 kHz mono
 *  impulse    = one full-scale sample at 1 s, 8 s long, 48 kHz stereo
 */
export async function makeFxFixtures(dir: string): Promise<FxFixtures> {
  fs.mkdirSync(dir, { recursive: true });
  const out = (name: string) => path.join(dir, name);
  const beepsExpr = "if(lt(mod(t\\,2)\\,0.05)\\,0.5*sin(2*PI*1000*t)\\,0)";
  ff(['-f', 'lavfi', '-i', `aevalsrc=${beepsExpr}|${beepsExpr}:s=48000:d=12`, '-c:a', 'pcm_f32le', out('beeps.wav')]);
  // logarithmic sweep: phase = 2π f0 T / ln(f1/f0) · (e^{t ln(f1/f0)/T} − 1)
  const sweepExpr = '0.5*sin(2*PI*20*6/log(1000)*(exp(t*log(1000)/6)-1))';
  ff(['-f', 'lavfi', '-i', `aevalsrc=${sweepExpr}|${sweepExpr}:s=48000:d=6`, '-c:a', 'pcm_f32le', out('sweep.wav')]);
  // a buzzy source at 150 Hz, two formant peaks (700 Hz, 1200 Hz), switched on and off four times a second
  const pulse = "if(lt(mod(t\\,1/150)\\,0.0007)\\,0.6\\,0)*if(lt(mod(t\\,0.25)\\,0.16)\\,1\\,0)";
  ff(['-f', 'lavfi', '-i', `aevalsrc=${pulse}|${pulse}:s=48000:d=10`, '-af', 'asplit[a][b];[a]bandpass=f=700:w=120[x];[b]bandpass=f=1200:w=160[y];[x][y]amix=inputs=2:normalize=0,volume=4', '-c:a', 'pcm_f32le', out('speechLike.wav')]);
  ff(['-f', 'lavfi', '-i', `aevalsrc=${beepsExpr}:s=44100:d=12`, '-c:a', 'pcm_f32le', out('mono44k.wav')]);
  const imp = 'if(eq(n\\,48000)\\,1\\,0)';
  ff(['-f', 'lavfi', '-i', `aevalsrc=${imp}|${imp}:s=48000:d=8`, '-c:a', 'pcm_f32le', out('impulse.wav')]);
  return { beeps: out('beeps.wav'), sweep: out('sweep.wav'), speechLike: out('speechLike.wav'), mono44k: out('mono44k.wav'), impulse: out('impulse.wav') };
}

/** Decode any audio file to interleaved stereo Float32 at `sampleRate` (mono becomes L = R). */
export function readStereo(file: string, sampleRate = 48000): Float32Array {
  const buf = execFileSync('ffmpeg', ['-hide_banner', '-v', 'error', '-i', file, '-ac', '2', '-ar', String(sampleRate), '-f', 'f32le', '-'], { maxBuffer: 1 << 30 });
  return new Float32Array(buf.buffer, buf.byteOffset, buf.byteLength / 4).slice();
}

/** Amplitude of the `hz` component of one channel over a window starting at `atSeconds` (Goertzel; a full-scale sine gives 1). */
export function goertzel(pcm: Float32Array, channel: 0 | 1, hz: number, atSeconds: number, sampleRate: number, windowSeconds = 0.1): number {
  const start = Math.max(0, Math.round(atSeconds * sampleRate)), n = Math.max(1, Math.round(windowSeconds * sampleRate));
  const frames = pcm.length / 2, end = Math.min(frames, start + n), count = end - start;
  if (count <= 0) return 0;
  const w = (2 * Math.PI * hz) / sampleRate, coeff = 2 * Math.cos(w);
  let s1 = 0, s2 = 0;
  for (let i = start; i < end; i++) {
    const hann = 0.5 - 0.5 * Math.cos((2 * Math.PI * (i - start)) / Math.max(1, count - 1));
    const s0 = pcm[i * 2 + channel]! * hann + coeff * s1 - s2;
    s2 = s1; s1 = s0;
  }
  const power = s1 * s1 + s2 * s2 - coeff * s1 * s2;
  return (2 * Math.sqrt(Math.max(0, power))) / (count * 0.5); // Hann window: coherent gain 0.5
}

/** Times (seconds) where the level of either channel first exceeds `threshold` after at least `holdSeconds` below it. */
export function onsets(pcm: Float32Array, sampleRate: number, threshold = 0.05, holdSeconds = 0.1): number[] {
  const out: number[] = [];
  const hold = Math.round(holdSeconds * sampleRate);
  let quiet = hold;
  for (let i = 0; i < pcm.length / 2; i++) {
    const v = Math.max(Math.abs(pcm[i * 2]!), Math.abs(pcm[i * 2 + 1]!));
    if (v > threshold) { if (quiet >= hold) out.push(i / sampleRate); quiet = 0; } else quiet++;
  }
  return out;
}

/** Levels (dB of RMS, both channels) in third-octave bands from 25 Hz to 16 kHz over [from, to) seconds, by FFT-free band filtering with Goertzel bins. */
export function thirdOctaveLevelsDb(pcm: Float32Array, sampleRate: number, fromSeconds: number, toSeconds: number): number[] {
  const centres: number[] = [];
  for (let k = -16; k <= 12; k++) centres.push(1000 * 2 ** (k / 3));
  const window = Math.max(0.01, toSeconds - fromSeconds);
  return centres.map((fc) => {
    // the band's energy as the mean of a few bins across it (adequate for comparing levels before and after an effect)
    const lo = fc / 2 ** (1 / 6), hi = fc * 2 ** (1 / 6);
    let sum = 0, n = 0;
    for (let j = 0; j < 5; j++) { const f = lo * (hi / lo) ** (j / 4); for (const ch of [0, 1] as const) { const a = goertzel(pcm, ch, f, fromSeconds, sampleRate, window); sum += a * a; n++; } }
    return 10 * Math.log10(Math.max(1e-20, sum / n / 2));
  });
}

/** Reverberation time (seconds to fall 60 dB) of an impulse response (mono or the left channel of stereo), from Schroeder's backward integral, fitted between -5 and -35 dB (T30). */
export function schroederRt60(impulseResponse: Float32Array, sampleRate: number): number {
  const x = impulseResponse;
  const energy = new Float64Array(x.length + 1);
  for (let i = x.length - 1; i >= 0; i--) energy[i] = energy[i + 1]! + x[i]! * x[i]!;
  const total = energy[0]!;
  if (!(total > 0)) return 0;
  const db = (i: number) => 10 * Math.log10(Math.max(1e-30, energy[i]! / total));
  let a = -1, b = -1;
  for (let i = 0; i < x.length; i++) { if (a < 0 && db(i) <= -5) a = i; if (db(i) <= -35) { b = i; break; } }
  if (a < 0 || b <= a) return 0;
  // least-squares slope of the decay curve between a and b
  let sx = 0, sy = 0, sxx = 0, sxy = 0, n = 0;
  for (let i = a; i <= b; i++) { const t = i / sampleRate, y = db(i); sx += t; sy += y; sxx += t * t; sxy += t * y; n++; }
  const slope = (n * sxy - sx * sy) / (n * sxx - sx * sx); // dB per second, negative
  return slope < 0 ? -60 / slope : 0;
}
